"""Restructure the dashboard while retaining existing forms and evidence handlers."""
from pathlib import Path
import re

root=Path(__file__).resolve().parents[1]
path=root/'app/index.html'
source=path.read_text(encoding='utf-8')
head=source[:source.index('</head>')]
head += '<link rel="stylesheet" href="/dashboard.css"></head>'
form=re.search(r'<form id="form">.*?</form>',source,re.S)[0]
settings=re.search(r'<form id="updateSettings".*?</form>',source,re.S)[0]
limits=re.search(r'<form id="roundLimitSettings">.*?</form>',source,re.S)[0]
extend=re.search(r'<form id="extendRounds".*?</form>',source,re.S)[0]
activity=re.search(r'<div id="activityCard".*?</div></div>',source,re.S)[0]
history=source[source.index('<section class="panel" id="agentHistory">'):]
history=history[:history.index('</section>')+len('</section>')]
dialogs=source[source.index('<dialog class="media-dialog"'):source.index('<script>')]
script=source[source.index('<script>'):]
nav=[('overview','Обзор','01'),('acceptance','Приёмка','02'),('media','Материалы','03'),('agents','Агенты и память','04'),('usage','Расход','05'),('settings','Настройки','06')]
navigation=''.join(f'<button type="button" data-view="{key}" aria-controls="view-{key}"'+(' aria-current="page"' if key=='overview' else '')+f'><span class="nav-icon" aria-hidden="true">{icon}</span>{label}</button>' for key,label,icon in nav)
body='''<body class="lab-shell"><a class="skip-link" href="#workspace">К содержимому</a>
<header class="lab-header"><div class="lab-brand"><span class="brand-mark" aria-hidden="true">C</span><div><h1>Development Lab</h1><span class="muted">Разработка модов Minecraft</span></div></div><div class="header-actions"><span id="connectionState" class="muted" role="status">Подключение…</span><button type="button" class="primary" id="newProjectOpen">＋ Новый проект</button></div></header>
<div class="lab-layout"><aside class="lab-sidebar" aria-label="Проекты и навигация"><details class="project-picker" open><summary>Проекты</summary><div id="jobs" class="muted">Загрузка…</div></details><p class="sidebar-label">Рабочее пространство</p><nav class="lab-nav" aria-label="Разделы проекта">'''+navigation+'''</nav><p class="sidebar-foot muted">Данные сохраняются на сервере.<br>Обновление страницы не сбрасывает работу.</p></aside>
<main id="workspace" tabindex="-1"><div class="workspace-header"><div><p class="eyebrow">Текущий проект</p><h2 id="title">Выбери проект</h2></div><span id="projectBadge" class="status">Нет задания</span></div>
<section class="lab-view" id="view-overview" data-page="overview" aria-labelledby="overviewHeading"><div class="view-heading"><div><h2 id="overviewHeading">Обзор</h2><p class="muted">Текущая работа и подтверждённые результаты.</p></div><div id="workspaceControls" class="row"><button id="pause" onclick="action('pause')" disabled>Пауза</button><button id="resume" class="primary" onclick="action('resume')" disabled>Продолжить</button><button id="stop" onclick="action('stop')" disabled>Остановить</button></div></div>
<div class="overview-grid"><section class="panel overview-summary"><p class="eyebrow">Приёмка по ТЗ</p><h3 id="readinessTitle">Нет данных</h3><progress id="readinessProgress" max="1" value="0" aria-label="Подтверждённые условия ТЗ"></progress><p id="readinessDetail" class="muted">Выбери проект для просмотра результатов.</p><p id="acceptanceSummary" class="muted" role="status">Готовность мода ещё не подтверждена.</p></section><section class="panel metric-card"><p class="eyebrow">Цикл разработки</p><div id="roundMetric" class="metric-value">—</div><p id="roundDetail" class="muted">Раунд — попытка работы и проверки.</p><button type="button" class="quick-link" data-go="settings">Изменить лимиты →</button></section></div>
<div id="workflow" class="workflow" aria-label="Этапы раунда"><span class="workflow-step" data-stage="plan">План</span><span aria-hidden="true">→</span><span class="workflow-step" data-stage="code">Код</span><span aria-hidden="true">→</span><span class="workflow-step" data-stage="test">Проверка</span><span aria-hidden="true">→</span><span class="workflow-step" data-stage="result">Результат</span></div>
'''+activity+'''<div id="overviewTaskSlot"></div><details id="projectDiagnostics" class="panel"><summary>Состояние и диагностика задания</summary><div id="status" class="muted">Выбери проект.</div></details></section>
<section class="lab-view" id="view-acceptance" data-page="acceptance" hidden aria-label="Приёмка по ТЗ"><p id="acceptanceEmpty" class="muted">Выбери проект, чтобы открыть приёмку.</p></section>
<section class="lab-view" id="view-media" data-page="media" hidden aria-labelledby="mediaHeading"><div class="view-heading"><div><h2 id="mediaHeading">Материалы</h2><p class="muted">Видео, скриншоты и JAR по раундам.</p></div></div><section class="panel"><div id="files" class="muted">Результатов пока нет.</div></section><details class="panel"><summary>Резервные копии и облачное хранилище</summary><div id="backups" class="muted">Резервных копий пока нет.</div><div id="s3" class="muted"></div></details></section>
<section class="lab-view" id="view-agents" data-page="agents" hidden aria-labelledby="agentsHeading"><div class="view-heading"><div><h2 id="agentsHeading">Агенты и память</h2><p class="muted">Назначения, решения и история по раундам.</p></div></div><div id="memorySlot"></div><details class="panel" id="plannerDetails"><summary>Планировщик и ручные проверки</summary><div id="plannerSlot"></div></details>'''+history+'''<details class="panel"><summary>Журнал контроллера</summary><pre id="events">Событий пока нет.</pre></details><details class="panel"><summary>Отчёт независимой проверки · JSON</summary><pre id="verification">Пока нет результатов.</pre></details></section>
<section class="lab-view" id="view-usage" data-page="usage" hidden aria-labelledby="usagePageHeading"><div class="view-heading"><div><h2 id="usagePageHeading">Расход API</h2><p class="muted">Учёт токенов и запросов. Данные Codex недоступны.</p></div></div><div id="usageSlot"></div><section class="panel"><h3>Токены по ролям</h3><div id="usageChart" class="usage-bars" aria-label="Распределение токенов по ролям"><p class="muted">Данных пока нет.</p></div><p class="foot">Длина полосы показывает долю учтённых токенов, а не прогресс разработки.</p></section></section>
<section class="lab-view" id="view-settings" data-page="settings" hidden aria-labelledby="settingsHeading"><div class="view-heading"><div><h2 id="settingsHeading">Модели и лимиты</h2><p class="muted">Изменения действуют для следующих запусков. Сначала приостанови задание.</p></div></div><div id="modelsSlot"></div><details class="panel" id="baseModelSettings"><summary>Общие настройки и бюджет API</summary><p class="muted">Роли без собственного выбора наследуют эти настройки. Выбор модели по роли имеет приоритет.</p>'''+settings+'''</details><section class="panel"><h3>Лимит раундов</h3>'''+limits+extend+'''</section></section>
</main></div><dialog id="newProjectDialog" class="acceptance-dialog lab-create-dialog" aria-labelledby="newProjectTitle"><header><h2 id="newProjectTitle">Новый проект</h2><button type="button" id="newProjectClose">Закрыть</button></header><p class="muted">Загрузи ТЗ в формате Markdown. Skills подключаются автоматически.</p>'''+form+'''<p class="foot">Модели по ролям можно изменить после создания проекта. Раунд не означает готовность мода.</p><p id="upload" role="status"></p></dialog>
'''+dialogs
source=head+body+script
source=source.replace('<script src="/agent-models.js"></script>','<script src="/agent-models.js"></script><script src="/dashboard.js"></script>')
source=source.replace("q('acceptanceDialog').showModal();refreshAcceptance()","if(window.labOpenAcceptance)window.labOpenAcceptance();else q('acceptanceDialog').showModal();refreshAcceptance()")
# Feed the presentation layer only confirmed API data. Keep media nodes mounted.
source=source.replace('  acceptanceData=data;','  acceptanceData=data;\n  window.dispatchEvent(new CustomEvent(\'lab-acceptance\',{detail:{job_id:jid,data}}));')
source=source.replace("q('jobs').replaceChildren();for(let j of jobs){let v=el('div','item');v.append(el('div','',j.title),el('small', 'status '+j.status,roundStatus(j)+' · раунд '+displayRound(j)+'/'+roundLimitText(j)+' · '+modelSelectionSummary(j).replaceAll('\\n',' | ')));v.onclick=()=>{active=j.id;activitySwitchJob(active);acceptanceSwitchJob(active);refresh()};q('jobs').append(v)}", "if(window.labRenderProjects)window.labRenderProjects(jobs);else{q('jobs').replaceChildren();for(let j of jobs){let v=el('button','item',j.title);v.type='button';v.onclick=()=>{active=j.id;activitySwitchJob(active);acceptanceSwitchJob(active);refresh()};q('jobs').append(v)}}")
source=source.replace("if(j.id!==active)return;refreshCurrentActivity(j);", "if(j.id!==active)return;window.dispatchEvent(new CustomEvent('lab-job',{detail:j}));refreshCurrentActivity(j);")
source=source.replace("q('upload').textContent='Проект создан: '+res.project_id;active=res.job_id;", "q('upload').textContent='Проект создан: '+res.project_id;window.dispatchEvent(new Event('lab-created'));active=res.job_id;")
path.write_text(source,encoding='utf-8')
